//! Who owns a file Orq may see in a project: Orq never deletes, moves or
//! rewrites what the project or the TDD/MCP tooling owns.

use std::path::{Component, Path};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Ownership {
    /// Defined by the project (`.tdd-features.json`).
    Project,
    /// Generated by the TDD or project MCP servers.
    Mcp,
    /// Not a known tool file.
    Unowned,
}

const MCP_FILES: [&str; 3] = [".mcp.json", ".project-mcp", ".mcpctl"];
const MCP_PREFIXES: [&str; 2] = [".tdd-", ".mcpctl"];

/// Classifies a file by its name alone.
pub fn classify(name: &str) -> Ownership {
    if name == ".tdd-features.json" {
        return Ownership::Project;
    }
    if MCP_FILES.contains(&name) || MCP_PREFIXES.iter().any(|prefix| name.starts_with(prefix)) {
        return Ownership::Mcp;
    }
    Ownership::Unowned
}

/// Whether a generic Orq cleanup may delete `path`. Being unrecognised is not
/// ownership: the path must lie inside `orq_root` (lexically, with no `..`),
/// must not be the root itself, and must not be a project or MCP file.
pub fn may_orq_delete(orq_root: &Path, path: &Path) -> bool {
    let Ok(inside) = path.strip_prefix(orq_root) else { return false };
    if inside.as_os_str().is_empty() || inside.components().any(|c| !matches!(c, Component::Normal(_))) {
        return false;
    }
    if !path.file_name().and_then(|name| name.to_str()).is_some_and(|name| classify(name) == Ownership::Unowned) {
        return false;
    }
    // A symlinked directory between the root and the file would redirect the
    // deletion outside the root, so no existing ancestor may be a symlink.
    let mut ancestor = orq_root.to_path_buf();
    let parts: Vec<_> = inside.components().collect();
    for part in &parts[..parts.len() - 1] {
        ancestor.push(part);
        if std::fs::symlink_metadata(&ancestor).is_ok_and(|meta| meta.file_type().is_symlink()) {
            return false;
        }
    }
    true
}

/// Deletes the file `rel` (relative to `orq_root`) without ever trusting a
/// path check made earlier: the root is opened once (a root that is itself a
/// symlink is refused), each directory is opened relative to its parent handle
/// refusing symlinks, and the file is unlinked relative to the final handle.
/// A symlink swapped in for the root or any directory beneath it makes the
/// deletion fail rather than be followed. Threat model: the ancestors *of* the
/// root are trusted, and so are processes able to rename directories inside it
/// (that needs the same privilege as Orq itself); a directory renamed out of
/// the root after it was opened is still deleted from through its handle.
#[cfg(unix)]
pub fn delete_in_root(orq_root: &Path, rel: &Path) -> std::io::Result<()> {
    use rustix::fs::{open, openat, unlinkat, AtFlags, Mode, OFlags};
    use std::io::{Error, ErrorKind};

    let denied = |why: &str| Error::new(ErrorKind::PermissionDenied, why.to_string());
    let mut parts = Vec::new();
    for component in rel.components() {
        match component {
            Component::Normal(part) => parts.push(part),
            _ => return Err(denied("path must stay inside the Orq root")),
        }
    }
    let (name, dirs) = parts.split_last().ok_or_else(|| denied("nothing to delete"))?;
    if !name.to_str().is_some_and(|name| classify(name) == Ownership::Unowned) {
        return Err(denied("tool and project files are not Orq's to delete"));
    }
    let flags = OFlags::RDONLY | OFlags::DIRECTORY | OFlags::CLOEXEC;
    // O_NOFOLLOW only guards the last path component, and `orq/` or `orq/.`
    // would hide the root's own entry from it, so open the root's parent
    // (trusted) and then the root by name, as `Path` normalises the spelling.
    let root_name = orq_root.file_name().ok_or_else(|| denied("the Orq root must name a directory"))?;
    let parent = match orq_root.parent() {
        Some(parent) if !parent.as_os_str().is_empty() => parent,
        _ => Path::new("."),
    };
    let parent = open(parent, flags, Mode::empty())?;
    let mut dir = openat(&parent, root_name, flags | OFlags::NOFOLLOW, Mode::empty())?;
    for part in dirs {
        dir = openat(&dir, *part, flags | OFlags::NOFOLLOW, Mode::empty())?;
    }
    unlinkat(&dir, *name, AtFlags::empty())?;
    Ok(())
}
